}

void quadtree_bounds_extend(quadtree_bounds_t *bounds, double x, double y){
  bounds->nw->x = fmin(x, bounds->nw->x);
  bounds->nw->y = fmax(y, bounds->nw->y);
  bounds->se->x = fmax(x, bounds->se->x);
  bounds->se->y = fmin(y, bounds->se->y);
  bounds->width = fabs(bounds->nw->x - bounds->se->x);
  bounds->height = fabs(bounds->nw->y - bounds->se->y);
}

quadtree_node_t* quadtree_node_new() {
  quadtree_node_t *node;
  if(!(node = malloc(sizeof(*node)))) return ((void*)0);
  node->ne = ((void*)0);
  node->nw = ((void*)0);
  node->se = ((void*)0);
  node->sw = ((void*)0);
  node->point = ((void*)0);
  node->bounds = ((void*)0);
  node->key = ((void*)0);
  return node;
}

void quadtree_node_free(quadtree_node_t* node, void (*key_free)(void*)) {
  if(node->nw != ((void*)0)) quadtree_node_free(node->nw, key_free);
  if(node->ne != ((void*)0)) quadtree_node_free(node->ne, key_free);
  if(node->sw != ((void*)0)) quadtree_node_free(node->sw, key_free);
  if(node->se != ((void*)0)) quadtree_node_free(node->se, key_free);
  quadtree_bounds_free(node->bounds);
  quadtree_node_reset(node, key_free);
  free(node);
}

int quadtree_node_ispointer(quadtree_node_t *node){
  return node->nw != ((void*)0) && node->ne != ((void*)0) && node->sw != ((void*)0) && node->se != ((void*)0) && !quadtree_node_isleaf(node);
}

int quadtree_node_isempty(quadtree_node_t *node){
  return node->nw == ((void*)0) && node->ne == ((void*)0) && node->sw == ((void*)0) && node->se == ((void*)0) && !quadtree_node_isleaf(node);
}

quadtree_node_t* quadtree_node_with_bounds(double minx, double miny, double maxx, double maxy){
  quadtree_node_t* node;
  if(!(node = quadtree_node_new())) return ((void*)0);
  if(!(node->bounds = quadtree_bounds_new())) return ((void*)0);
  quadtree_bounds_extend(node->bounds, maxx, maxy);
  quadtree_bounds_extend(node->bounds, minx, miny);
  return node;
}

quadtree_point_t* quadtree_point_new(double x, double y) {
  quadtree_point_t* point;
  if(!(point = malloc(sizeof(*point)))) return ((void*)0);
  point->x = x;
  point->y = y;
  return point;
}

quadtree_t* quadtree_new(double minx, double miny, double maxx, double maxy) {
  quadtree_t *tree;
  if(!(tree = malloc(sizeof(*tree)))) return ((void*)0);
  tree->root = quadtree_node_with_bounds(minx, miny, maxx, maxy);
  if(!(tree->root)) return ((void*)0);
  tree->key_free = ((void*)0);
  tree->length = 0;
  return tree;
}

void quadtree_free(quadtree_t *tree) {
  if(tree->key_free != ((void*)0)) {
    quadtree_node_free(tree->root, tree->key_free);
  } else {
    quadtree_node_free(tree->root, elision_);
  }
  free(tree);
}

quadtree_point_t* quadtree_search(quadtree_t *tree, double x, double y) {
  return find_(tree->root, x, y);
}

int quadtree_insert(quadtree_t *tree, double x, double y, void *key) {
  quadtree_point_t *point;
  if(!(point = quadtree_point_new(x, y))) return 0;
  if(!node_contains_(tree->root, point)) return 0;
  if(!insert_(tree, tree->root, point, key)) return 0;
  tree->length++;
  return 1;
}

void quadtree_walk(quadtree_node_t *root, void (*descent)(quadtree_node_t *node), void (*ascent)(quadtree_node_t *node)) {
  (*descent)(root);
  if(root->nw != ((void*)0)) quadtree_walk(root->nw, descent, ascent);
  if(root->ne != ((void*)0)) quadtree_walk(root->ne, descent, ascent);
  if(root->sw != ((void*)0)) quadtree_walk(root->sw, descent, ascent);
  if(root->se != ((void*)0)) quadtree_walk(root->se, descent, ascent);
  (*ascent)(root);
}

static int split_node_(quadtree_t *tree, quadtree_node_t *node){
  quadtree_node_t *nw;
  quadtree_node_t *ne;
  quadtree_node_t *sw;
  quadtree_node_t *se;
  double x = node->bounds->nw->x;
  double y = node->bounds->nw->y;
  double hw = node->bounds->width / 2;
  double hh = node->bounds->height / 2;
  if(!(nw = quadtree_node_with_bounds(x, y - hh, x + hw, y))) return 0;
  if(!(ne = quadtree_node_with_bounds(x + hw, y - hh, x + hw * 2, y))) return 0;
  if(!(sw = quadtree_node_with_bounds(x, y - hh * 2, x + hw, y - hh))) return 0;
  if(!(se = quadtree_node_with_bounds(x + hw, y - hh * 2, x + hw * 2, y - hh))) return 0;
  node->nw = nw;
  node->ne = ne;
  node->sw = sw;
  node->se = se;
  quadtree_point_t *old = node->point;
  void *key = node->key;
  node->point = ((void*)0);
  node->key = ((void*)0);
  return insert_(tree, node, old, key);
}

static int insert_(quadtree_t* tree, quadtree_node_t *root, quadtree_point_t *point, void *key) {
  if(quadtree_node_isempty(root)) {
    root->point = point;
    root->key = key;
    return 1;
  } else if(quadtree_node_isleaf(root)){
    if(root->point->x == point->x && root->point->y == point->y){
      reset_node_(tree, root);
      root->point = point;
      root->key = key;
      return 0;
    } else {
      if(!split_node_(tree, root)) return 0;
      return insert_(tree, root, point, key);
    }
    return 1;
  } else if(quadtree_node_ispointer(root)){
    quadtree_node_t* quadrant = get_quadrant_(root, point);
    return quadrant == ((void*)0) ? 0 : insert_(tree, quadrant, point, key);
  }
  return 0;
}

static int node_contains_(quadtree_node_t *outer, quadtree_point_t *it) {
  return outer->bounds != ((void*)0) && outer->bounds->nw->x < it->x && outer->bounds->nw->y > it->y && outer->bounds->se->x > it->x && outer->bounds->se->y < it->y;
}

static quadtree_node_t * get_quadrant_(quadtree_node_t *root, quadtree_point_t *point) {
  if(node_contains_(root->nw, point)) return root->nw;
  if(node_contains_(root->ne, point)) return root->ne;
  if(node_contains_(root->sw, point)) return root->sw;
  if(node_contains_(root->se, point)) return root->se;
  return ((void*)0);
}

static void reset_node_(quadtree_t *tree, quadtree_node_t *node){
  if(tree->key_free != ((void*)0)) {
    quadtree_node_reset(node, tree->key_free);
  } else {
    quadtree_node_reset(node, elision_);
  }
}

static quadtree_point_t* find_(quadtree_node_t* node, double x, double y) {
  if(quadtree_node_isleaf(node)) {
    if(node->point->x == x && node->point->y == y) return node->point;
  } else {
    quadtree_point_t test;
    test.x = x;
    test.y = y;
    return find_(get_quadrant_(node, &test), x, y);
  }
  return ((void*)0);
}
